<script setup lang="ts">const{session,requests,tenants,authorizedTenantAudit,load}=usePlatformAdminWorkspace();const reportDateFrom=ref(''),reportDateTo=ref(''),selectedChatRequestId=ref(''),selectedOperationalRequestId=ref(''),reportLoading=ref(false),error=ref('');const auditRequests=computed(()=>requests.value.filter(request=>request.category==='audit'&&request.decision==='approved'&&Boolean(request.expiresAt&&new Date(request.expiresAt).getTime()>Date.now())));const label=(request:any)=>`${request.id} - ${request.subject}`;const period=()=>new URLSearchParams({...reportDateFrom.value?{from:reportDateFrom.value}:{},...reportDateTo.value?{to:reportDateTo.value}:{}}).toString();const downloadAdministrativeReport=async()=>{reportLoading.value=true;error.value='';try{const query=period();await session.download(`/api/platform-admin/audit-export${query?`?${query}`:''}`,'Relatorio_Atividades_Administrativas.csv')}catch(cause:any){error.value=cause?.message||'Nao foi possivel gerar o relatorio administrativo.'}finally{reportLoading.value=false}};const downloadChatReport=async()=>{if(!selectedChatRequestId.value)return;reportLoading.value=true;error.value='';try{const query=period();await session.download(`/api/platform-admin/support-requests/${encodeURIComponent(selectedChatRequestId.value)}/report${query?`?${query}`:''}`,`Relatorio_Conversa_${selectedChatRequestId.value}.csv`)}catch(cause:any){error.value=cause?.message||'Nao foi possivel gerar o relatorio da conversa.'}finally{reportLoading.value=false}};const openCompanyEvents=async()=>{const request=auditRequests.value.find(item=>item.id===selectedOperationalRequestId.value);const tenant=request&&tenants.value.find(item=>item.id===request.tenantId);if(!request||!tenant)return;reportLoading.value=true;error.value='';try{const query=period();const events=await session.request<any[]>(`/api/platform-admin/tenants/${encodeURIComponent(tenant.id)}/audit?accessRequestId=${encodeURIComponent(request.id)}${query?`&${query}`:''}`);authorizedTenantAudit.value={tenant,accessRequestId:request.id,events};await navigateTo('/auditoria?secao=empresa')}catch(cause:any){error.value=cause?.data?.error||cause?.message||'A autorizacao para este relatorio nao esta mais valida.'}finally{reportLoading.value=false}};onMounted(()=>void load({requests:true,tenants:true}))</script>
<template><div><p v-if="error" class="feedback feedback--error">{{error}}</p><section class="audit-guide" aria-label="Tipos de relatorio"><article><strong>Atividades administrativas</strong><span>Acoes dos superadmins, com periodo opcional.</span></article><article><strong>Historico de atendimento</strong><span>Registro de um protocolo especifico.</span></article><article><strong>Eventos de empresa</strong><span>Exige autorizacao aprovada e acesso temporario.</span></article></section><section class="panel"><div class="panel-head"><div><h2>Exportar relatorio</h2><p>Cada exportacao fica registrada na auditoria.</p></div></div><div class="inline-actions" style="justify-content:flex-start;flex-wrap:wrap"><input v-model="reportDateFrom" type="date" aria-label="Data inicial"><input v-model="reportDateTo" type="date" aria-label="Data final"><button class="button button--primary" :disabled="reportLoading" @click="downloadAdministrativeReport">Atividades administrativas</button><select v-model="selectedChatRequestId" aria-label="Protocolo da conversa"><option value="">Selecione uma conversa</option><option v-for="request in requests" :key="request.id" :value="request.id">{{label(request)}}</option></select><button class="button button--quiet" :disabled="reportLoading||!selectedChatRequestId" @click="downloadChatReport">Historico do chat</button><select v-model="selectedOperationalRequestId" aria-label="Protocolo autorizado"><option value="">Selecione uma autorizacao aprovada</option><option v-for="request in auditRequests" :key="request.id" :value="request.id">{{label(request)}}</option></select><button class="button button--quiet" :disabled="reportLoading||!selectedOperationalRequestId" @click="openCompanyEvents">Eventos da empresa</button></div></section></div></template>
